package com.leetcode.backend.model;import jakarta.persistence.*;import java.time.LocalDate;
@Entity @Table(name="daily_challenges",uniqueConstraints=@UniqueConstraint(columnNames="challengeDate"))public class DailyChallenge{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private LocalDate challengeDate;@ManyToOne(optional=false)@JoinColumn(name="problem_id")private Problem problem;public Long getId(){return id;}public LocalDate getChallengeDate(){return challengeDate;}public void setChallengeDate(LocalDate v){challengeDate=v;}public Problem getProblem(){return problem;}public void setProblem(Problem v){problem=v;}}
